                        ctx["sigma0_mult"] = float(ss.get("ga_sigma0_mult", 1.5) or 1.5)
                        ctx["sigma_floor"] = float(ss.get("ga_sigma_floor", 0.0) or 0.0)
                        ctx["damps_mult"] = float(ss.get("ga_damps_mult", 1.5) or 1.5)

