                                log(f"   [inc-build] incidence matrix built in "
                                    f"{_ib_t3 - _ib_t0:.1f}s — {len(_rows):,} non-zero(s) in a "
                                    f"{max(len(_pbp_x.prop_keys), 1):,}x{len(G):,} matrix.")
